THOUGHT: The checks require a self-contained service with shared durable state across three HTTP ports, WebSocket delivery, IRC, and a browser surface. I’ll create a standard-library implementation backed by one SQLite database, with a supervisor that launches all nodes and the IRC listener, plus a SPA containing the pinned hooks and basic message/thread/reaction flows.

```mswea_bash_command
cat > /app/server.py <<'PY'
import os, re, json, sqlite3, hashlib, secrets, threading, time, base64, socket, struct, mimetypes
from datetime import datetime, timezone
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs, unquote
DB='/app/huddle.db'
LOCK=threading.RLock()
clients={}
def now(): return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def db():
    c=sqlite3.connect(DB,check_same_thread=False); c.row_factory=sqlite3.Row
    c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
    CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
    CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
    CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',archived INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS cmembers(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
    CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0,event_id INTEGER);
    CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
    CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,created_at TEXT,data BLOB,attached INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS dms(a INTEGER,b INTEGER,channel_id INTEGER,UNIQUE(a,b));
    CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,user_ids TEXT);
    CREATE TABLE IF NOT EXISTS readstate(user_id INTEGER,channel_id INTEGER,last_read INTEGER DEFAULT 0,PRIMARY KEY(user_id,channel_id));''')
    return c
def objuser(r):
    return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def user(uid):
    c=db(); r=c.execute('select * from users where id=?',(uid,)).fetchone(); c.close(); return objuser(r) if r else None
def channel(r):
    return {'id':r['id'],'workspace_id':r['workspace_id'],'name':r['name'],'is_private':bool(r['is_private']),'is_dm':bool(r['is_dm']),'topic':r['topic'],'is_archived':bool(r['archived'])}
def msg(r):
    c=db(); u=c.execute('select * from users where id=?',(r['author_id'],)).fetchone()
    rs=c.execute('select emoji,count(*) n,group_concat(user_id) ids from reactions where message_id=? group by emoji',(r['id'],)).fetchall()
    replies=c.execute('select count(*) n from messages where parent_id=? and deleted=0',(r['id'],)).fetchone()['n']; c.close()
    return {'id':r['id'],'channel_id':r['channel_id'],'author_id':r['author_id'],'author':objuser(u),'body':r['body'],'parent_id':r['parent_id'],'reply_count':replies,'created_at':r['created_at'],'edited_at':r['edited_at'],'files':[],'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(i) for i in x['ids'].split(',')]} for x in rs],'mentions':[]}
def init_event(c,cid):
    x=c.execute('select coalesce(max(event_id),0) n from messages where channel_id=?',(cid,)).fetchone()['n']; return x
def broadcast(cid,frame):
    raw=json.dumps(frame).encode()
    for s in list(clients.get(cid,[])):
        try: ws_send(s,raw)
        except: clients[cid].discard(s)
def ws_send(s,p):
    if isinstance(p,str): p=p.encode()
    n=len(p); h=bytes([0x81])+ (bytes([n]) if n<126 else bytes([126])+struct.pack('!H',n))
    s.sendall(h+p)
def ws_recv(s):
    h=s.recv(2)
    if len(h)<2:return None
    n=h[1]&127
    if n==126:n=struct.unpack('!H',s.recv(2))[0]
    if h[1]&128:m=s.recv(4)
    else:m=None
    p=s.recv(n)
    if m:p=bytes(x^m[i%4] for i,x in enumerate(p))
    return p
class H(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def sendj(self,status,x,headers=None):
        b=json.dumps(x).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b)))
        for k,v in (headers or {}).items():self.send_header(k,v)
        self.end_headers(); self.wfile.write(b)
    def body(self):
        n=int(self.headers.get('Content-Length','0')); return self.rfile.read(n)
    def auth(self):
        t=self.headers.get('Authorization','').removeprefix('Bearer ').strip(); c=db(); r=c.execute('select user_id from tokens where token=?',(t,)).fetchone(); c.close(); return r['user_id'] if r else None
    def path(self): return urlparse(self.path).path
    def do_GET(self):
        p=self.path(); q=parse_qs(urlparse(self.path).query)
        if p=='/': return self.html()
        if p=='/api/health': return self.sendj(200,{'status':'ok','node_id':int(os.getenv('NODE_ID','0'))})
        if p=='/api/ws': return self.websocket(q.get('token',[''])[0])
        uid=self.auth()
        if p=='/api/auth/me':
            if not uid:return self.sendj(401,{'error':'unauthorized'})
            return self.sendj(200,{'user':user(uid)})
        if p.startswith('/api/users/'):
            x=user(int(p.split('/')[-1])); return self.sendj(200,{'user':x}) if x else self.sendj(404,{'error':'not found'})
        if not uid:return self.sendj(401,{'error':'unauthorized'})
        c=db()
        if p=='/api/workspaces':
            rows=c.execute('select w.* from workspaces w join members m on m.workspace_id=w.id where m.user_id=?',(uid,)).fetchall(); return self.sendj(200,{'workspaces':[dict(x) for x in rows]})
        m=re.match(r'/api/workspaces/([^/]+)$',p)
        if m:
            w=c.execute('select * from workspaces where slug=?',(m.group(1),)).fetchone()
            if not w:return self.sendj(404,{'error':'not found'})
            cs=c.execute('select * from channels where workspace_id=? and archived=0',(w['id'],)).fetchall()
            return self.sendj(200,{'workspace':dict(w),'channels':[channel(x) for x in cs],'read_state':[]})
        m=re.match(r'/api/channels/(\d+)/messages',p)
        if m:
            rows=c.execute('select * from messages where channel_id=? and deleted=0 order by id desc limit 200',(int(m.group(1)),)).fetchall()
            return self.sendj(200,{'messages':[msg(x) for x in rows],'next_cursor':None})
        m=re.match(r'/api/messages/(\d+)/replies',p)
        if m:
            rows=c.execute('select * from messages where parent_id=? and deleted=0 order by id',(int(m.group(1)),)).fetchall()
            return self.sendj(200,{'replies':[msg(x) for x in rows],'next_cursor':None})
        if p.startswith('/api/files/'):
            fid=int(p.split('/')[3]); f=c.execute('select * from files where id=?',(fid,)).fetchone()
            if not f:return self.sendj(404,{'error':'not found'})
            if p.endswith('/download'):
                self.send_response(200);self.send_header('Content-Type',f['content_type']);self.send_header('Content-Disposition',f'attachment; filename="{f["filename"]}"');self.end_headers();self.wfile.write(f['data']);return
            return self.sendj(200,{'file':{k:f[k] for k in ('id','uploader_id','filename','content_type','size','created_at')}})
        return self.sendj(404,{'error':'not found'})
    def do_POST(self):
        p=self.path(); uid=self.auth(); data={}
        try:data=json.loads(self.body() or b'{}')
        except:pass
        if p=='/api/auth/register':
            u=data.get('username',''); pw=data.get('password','')
            if not re.fullmatch(r'[A-Za-z0-9_]+',u) or len(pw)<8:return self.sendj(400,{'error':'invalid'})
            c=db()
            try:c.execute('insert into users(username,password,display_name) values(?,?,?)',(u,pw,data.get('display_name') or u));c.commit()
            except:return self.sendj(409,{'error':'duplicate'})
            r=c.execute('select * from users where username=?',(u,)).fetchone(); t=secrets.token_urlsafe(24);c.execute('insert into tokens values(?,?)',(t,r['id']));c.commit();c.close();return self.sendj(201,{'user':objuser(r),'token':t})
        if p=='/api/auth/login':
            c=db();r=c.execute('select * from users where username=? and password=?',(data.get('username'),data.get('password'))).fetchone()
            if not r:return self.sendj(401,{'error':'invalid'})
            t=secrets.token_urlsafe(24);c.execute('insert into tokens values(?,?)',(t,r['id']));c.commit();c.close();return self.sendj(200,{'user':objuser(r),'token':t})
        if not uid:return self.sendj(401,{'error':'unauthorized'})
        c=db()
        if p=='/api/workspaces':
            slug=data.get('slug',''); 
            if not re.fullmatch(r'[a-z0-9-]{2,32}',slug):return self.sendj(400,{'error':'invalid'})
            try:c.execute('insert into workspaces(slug,name,owner_id) values(?,?,?)',(slug,data.get('name',slug),uid));wid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into members values(?,?,?)',(wid,uid,'owner'));c.execute('insert into channels(workspace_id,name) values(?,?)',(wid,'general'));cid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into cmembers values(?,?)',(cid,uid));c.commit()
            except:return self.sendj(409,{'error':'duplicate'})
            w=c.execute('select * from workspaces where id=?',(wid,)).fetchone();ch=c.execute('select * from channels where id=?',(cid,)).fetchone();return self.sendj(201,{'workspace':dict(w),'general_channel':channel(ch)})
        m=re.match(r'/api/channels/(\d+)/join',p)
        if m:
            cid=int(m.group(1));r=c.execute('select * from channels where id=?',(cid,)).fetchone()
            if not r:return self.sendj(404,{})
            c.execute('insert or ignore into cmembers values(?,?)',(cid,uid));c.execute('insert or ignore into members values(?,?,?)',(r['workspace_id'],uid,'member'));c.commit();return self.sendj(200,{'channel':channel(r)})
        m=re.match(r'/api/workspaces/([^/]+)/channels$',p)
        if m:
            w=c.execute('select * from workspaces where slug=?',(m.group(1),)).fetchone(); name=data.get('name','')
            if not w:return self.sendj(404,{})
            if c.execute('select 1 from channels where workspace_id=? and name=?',(w['id'],name)).fetchone():return self.sendj(409,{})
            c.execute('insert into channels(workspace_id,name,is_private,topic) values(?,?,?,?)',(w['id'],name,int(bool(data.get('is_private'))),data.get('topic','')));c.commit();return self.sendj(201,{'channel':channel(c.execute('select * from channels where id=last_insert_rowid()').fetchone())})
        m=re.match(r'/api/channels/(\d+)/messages$',p)
        if m:
            cid=int(m.group(1)); body=data.get('body','')
            if not body.strip():return self.sendj(400,{'error':'empty'})
            if body.startswith('/') and not body.startswith('//'):
                if body.startswith('/shrug'):body=body[6:].strip()+' ¯\\_(ツ)_/¯'
                elif body.startswith('/me '):pass
                elif body.startswith('/topic '):
                    c.execute('update channels set topic=? where id=?',(body[7:],cid));c.commit();return self.sendj(201,{'message':None,'channel':channel(c.execute('select * from channels where id=?',(cid,)).fetchone())})
                elif not body.startswith('/invite '):return self.sendj(400,{'error':'command'})
            eid=init_event(c,cid)+1; parent=data.get('parent_id');c.execute('insert into messages(channel_id,author_id,body,parent_id,created_at,event_id) values(?,?,?,?,?,?)',(cid,uid,body,parent,now(),eid));mid=c.execute('select last_insert_rowid()').fetchone()[0];c.commit();r=c.execute('select * from messages where id=?',(mid,)).fetchone();x=msg(r);broadcast(cid,{'type':'message.reply' if parent else 'message.created','event_id':eid,'channel_id':cid,'message':x});return self.sendj(201,{'message':x})
        m=re.match(r'/api/messages/(\d+)/reactions$',p)
        if m:
            mid=int(m.group(1));c.execute('insert or ignore into reactions values(?,?,?)',(mid,uid,data.get('emoji','')));c.commit();rows=c.execute('select emoji,count(*) n,group_concat(user_id) ids from reactions where message_id=? group by emoji',(mid,)).fetchall();return self.sendj(200,{'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(i) for i in x['ids'].split(',')]} for x in rows]})
        if p=='/api/dms':
            a,b=sorted((uid,int(data.get('user_id',0))));r=c.execute('select channel_id from dms where a=? and b=?',(a,b)).fetchone()
            if r:return self.sendj(200,{'channel_id':r['channel_id']})
            c.execute('insert into channels(name,is_dm) values(?,1)',(f'dm-{a}-{b}',));cid=c.execute('select last_insert_rowid()').fetchone()[0];c.execute('insert into dms values(?,?,?)',(a,b,cid));c.execute('insert into cmembers values(?,?),(?,?)',(cid,a,cid,b));c.commit();return self.sendj(200,{'channel_id':cid})
        return self.sendj(404,{})
    def do_PATCH(self):
        uid=self.auth()
        if not uid:return self.sendj(401,{})
        p=self.path(); data=json.loads(self.body() or b'{}');c=db()
        m=re.match(r'/api/messages/(\d+)$',p)
        if m:
            r=c.execute('select * from messages where id=?',(int(m.group(1)),)).fetchone()
            if not r:return self.sendj(404,{})
            c.execute('update messages set body=?,edited_at=? where id=?',(data.get('body',''),now(),r['id']));c.commit();x=msg(c.execute('select * from messages where id=?',(r['id'],)).fetchone());return self.sendj(200,{'message':x})
        return self.sendj(404,{})
    def do_DELETE(self):
        uid=self.auth();p=self.path()
        if not uid:return self.sendj(401,{})
        m=re.match(r'/api/messages/(\d+)/reactions/(.+)',p)
        if m:
            c=db();c.execute('delete from reactions where message_id=? and user_id=? and emoji=?',(int(m.group(1)),uid,unquote(m.group(2))));c.commit();rows=c.execute('select emoji,count(*) n,group_concat(user_id) ids from reactions where message_id=? group by emoji',(int(m.group(1)),)).fetchall();return self.sendj(200,{'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(i) for i in x['ids'].split(',')]} for x in rows]})
        return self.sendj(404,{})
    def do_PUT(self): self.do_POST()
    def websocket(self,t):
        uid=None;c=db();r=c.execute('select user_id from tokens where token=?',(t,)).fetchone()
        if r:uid=r['user_id']
        if not uid:return self.send_response(401)
        key=self.headers.get('Sec-WebSocket-Key'); accept=base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()
        self.send_response(101);self.send_header('Upgrade','websocket');self.send_header('Connection','Upgrade');self.send_header('Sec-WebSocket-Accept',accept);self.end_headers()
        while True:
            p=ws_recv(self.connection)
            if not p:break
            try:d=json.loads(p)
            except:continue
            cid=int(d.get('channel_id',0));clients.setdefault(cid,set()).add(self.connection); head=init_event(c,cid)
            if d.get('type')=='subscribe':ws_send(self.connection,json.dumps({'type':'subscribed','channel_id':cid,'head_event_id':head}))
            elif d.get('type')=='resume':ws_send(self.connection,json.dumps({'type':'resumed','channel_id':cid,'head_event_id':head}))
    def html(self):
        self.send_response(200);self.send_header('Content-Type','text/html');self.end_headers();self.wfile.write(HTML.encode())
HTML='''<!doctype html><html><head><meta charset=utf-8><style>body{margin:0;font:14px Arial;display:flex;height:100vh}.side{width:260px;background:#3f0f3f;color:white;padding:20px}.main{flex:1;padding:24px}.thread{width:300px;border-left:1px solid #ddd;padding:15px}button{border:0;padding:9px 14px;color:#fff;border-radius:4px}.primary{background:#007a5a}.danger{background:#e01e5a}.secondary{background:#1264a3}input{padding:9px;margin:4px}.msg{padding:12px;border-bottom:1px solid #eee}</style></head><body><aside class=side><h2 data-testid=workspace-header>Huddle</h2><div data-testid=current-user></div><button data-testid=logout-btn data-button-role=danger class=danger>Logout</button><h3>Channels</h3><div data-testid=channel-list></div><button data-testid=new-channel-btn data-button-role=secondary class=secondary>New channel</button></aside><main class=main><div data-testid=auth-modal><form data-testid=auth-form><input name=username placeholder=username><input name=password type=password placeholder=password><button data-testid=auth-submit data-button-role=primary class=primary>Login</button><button type=button data-testid=auth-toggle>Register</button></form></div><div id=create-channel-modal><form data-testid=create-channel-form><input name=name><input type=checkbox data-testid=create-channel-private><button data-testid=create-channel-submit data-button-role=primary class=primary>Create</button><button type=button data-testid=create-channel-cancel data-button-role=secondary class=secondary>Cancel</button></form></div><section><h2 data-testid=channel-title>#general</h2><div data-testid=channel-topic></div><div data-testid=message-list></div><input data-testid=message-input><button data-testid=send-btn data-button-role=primary class=primary>Send</button></section><div id=channel-settings-modal><button data-testid=channel-settings-btn data-button-role=secondary class=secondary>Settings</button><input data-testid=channel-topic-input><button data-testid=channel-topic-submit data-button-role=primary class=primary>Save</button><button data-testid=channel-settings-close data-button-role=secondary class=secondary>Close</button><button data-testid=archive-channel-btn data-button-role=danger class=danger>Archive</button><button data-testid=unarchive-channel-btn data-button-role=secondary class=secondary>Unarchive</button><div data-testid=channel-members-list></div></div><div id=workspace-settings-modal><button data-testid=workspace-settings-btn data-button-role=secondary class=secondary>Workspace</button><input data-testid=workspace-name-input><select data-testid=workspace-join-mode></select><button data-testid=workspace-general-submit data-button-role=primary class=primary>Save</button><button data-testid=workspace-settings-close data-button-role=secondary class=secondary>Close</button><button data-testid=settings-tab-members>Members</button><button data-testid=settings-tab-invitations>Invitations</button><button data-testid=settings-tab-general>General</button><div data-testid=settings-pane-members></div><div data-testid=settings-pane-invitations></div><div data-testid=settings-pane-general></div><button data-testid=create-invitation-btn data-button-role=secondary class=secondary>Create invite</button><form id=create-invitation-form data-testid=create-invitation-form><button data-testid=create-invitation-submit data-button-role=primary class=primary>Create</button></form><div data-testid=invitations-list></div></div><div data-testid=thread-panel style=display:none><button data-testid=close-thread data-button-role=secondary class=secondary>Close</button><div id=thread-messages></div><input data-testid=thread-input><button data-testid=thread-send data-button-role=primary class=primary>Reply</button></div></main><script>
let token=new URLSearchParams(location.search).get('token')||localStorage.getItem('huddle.token'),cid=null,mid=null;let $=x=>document.querySelector('[data-testid="'+x+'"]');function api(p,o={}){o.headers=Object.assign({'Content-Type':'application/json'},o.headers||{},token?{Authorization:'Bearer '+token}:{});return fetch('/api'+p,o).then(x=>x.json())}function render(){api('/workspaces').then(x=>{let w=x.workspaces?.[0];if(!w)return;api('/workspaces/'+w.slug).then(y=>{let cs=y.channels||[];cid=cid||cs[0]?.id;$('channel-list').innerHTML=cs.map(c=>'<div data-testid=channel-entry data-channel-id="'+c.id+'" data-channel-name="'+c.name+'">#'+c.name+'</div>').join('');document.querySelectorAll('[data-channel-entry]').forEach(e=>e.onclick=()=>{cid=e.dataset.channelId;load()});load()})})}function load(){api('/channels/'+cid+'/messages').then(x=>{$('message-list').innerHTML=x.messages.reverse().map(m=>'<div class=msg data-testid=message><b>'+m.author.display_name+'</b> <span data-testid=message-body>'+m.body+'</span><button data-testid=open-thread-btn>Replies</button><button data-testid=reaction-button>😊</button><span data-testid=reaction-chip>'+((m.reactions||[])[0]?.emoji||'')+'</span></div>').join('');document.querySelectorAll('[data-testid=open-thread-btn]').forEach((b,i)=>b.onclick=()=>{mid=x.messages.slice().reverse()[i].id;$('thread-panel').style.display='block'});document.querySelectorAll('[data-testid=reaction-button]').forEach((b,i)=>b.onclick=()=>api('/messages/'+x.messages.slice().reverse()[i].id+'/reactions',{method:'POST',body:JSON.stringify({emoji:'😊'})}).then(load))})}$('auth-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);api('/auth/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})}).then(x=>{token=x.token;localStorage.setItem('huddle.token',token);render()})};$('send-btn').onclick=()=>{let v=$('message-input').value;if(v.trim())api('/channels/'+cid+'/messages',{method:'POST',body:JSON.stringify({body:v})}).then(()=>{$('message-input').value='';load()})};$('thread-send').onclick=()=>{let v=$('thread-input').value;if(v&&mid)api('/channels/'+cid+'/messages',{method:'POST',body:JSON.stringify({body:v,parent_id:mid})}).then(load)};$('close-thread').onclick=()=>{$('thread-panel').style.display='none'};if(token){window.__huddle_token=token;render()} 
</script></body></html>'''
def irc_server():
    s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind(('0.0.0.0',6667));s.listen()
    while True:
        c,_=s.accept();threading.Thread(target=irc_client,args=(c,),daemon=True).start()
def irc_client(s):
    token=None;nick='guest'; registered=False
    f=s.makefile('rwb')
    def out(x):f.write((x+'\r\n').encode());f.flush()
    while True:
        line=f.readline()
        if not line:break
        z=line.decode(errors='ignore').strip(); a=z.split(' ',2); cmd=a[0].upper()
        if cmd=='PASS':token=a[1] if len(a)>1 else ''
        elif cmd=='NICK':nick=a[1] if len(a)>1 else nick
        elif cmd=='USER' and token:
            registered=True
            for n in ('001','002','003','004','005'):out(':huddle '+n+' '+nick+' :Welcome')
            out(':huddle 422 '+nick+' :MOTD File is missing')
        elif cmd=='PING':out('PONG '+(a[1] if len(a)>1 else ''))
        elif cmd=='QUIT':break
        elif cmd=='JOIN':
