    f=s.makefile('rwb')
    def out(x):f.write((x+'\r\n').encode());f.flush()
    while True:
        line=f.readline()
        if not line:break
        z=line.decode(errors='ignore').strip(); a=z.split(' ',2); cmd=a[0].upper()
        if cmd=='PASS':token=a[1] if len(a)>1 else ''
        elif cmd=='NICK':nick=a[1] if len(a)>1 else nick
        elif cmd=='USER' and token:
            registered=True
            for n in ('001','002','003','004','005'):out(':huddle '+n+' '+nick+' :Welcome')
            out(':huddle 422 '+nick+' :MOTD File is missing')
        elif cmd=='PING':out('PONG '+(a[1] if len(a)>1 else ''))
        elif cmd=='QUIT':break
        elif cmd=='JOIN':
            ch=a[1] if len(a)>1 else ''; out(':'+nick+'!user@localhost JOIN '+ch);out(':huddle 353 '+nick+' = '+ch+' :'+nick);out(':huddle 366 '+nick+' '+ch+' :End of NAMES')
        elif cmd=='PRIVMSG' and len(a)>2 and token:
            m=re.match(r'#([^/]+)/(.+)',a[1]); uid=None;c=db();r=c.execute('select user_id from tokens where token=?',(token,)).fetchone()
            if r and m:
                rr=c.execute('select c.* from channels c join workspaces w on w.id=c.workspace_id where w.slug=? and c.name=?',(m.group(1),m.group(2))).fetchone()
                if rr:
                    uid=r['user_id'];eid=init_event(c,rr['id'])+1;c.execute('insert into messages(channel_id,author_id,body,created_at,event_id) values(?,?,?,?,?)',(rr['id'],uid,a[2].lstrip(':'),now(),eid));c.commit();broadcast(rr['id'],{'type':'message.created','event_id':eid,'channel_id':rr['id']})
        else:
            if cmd not in ('USER','NICK','PASS'):out(':huddle 421 '+nick+' '+cmd+' :Unknown command')
